//! Prothesis: the laying-out of the dead. A shrouded body on a bier, a lamp at its
//! head, mourners with their hands to their heads; time only takes away, then stops.
use crate::_0_profile::measure_layer;
use crate::opts::param_f32;
use crate::registry::{AnimKind, Mode, ModeFrame, Param};
use crate::types::{Cell, Grid};
use crossterm::style::Color;
use std::cell::RefCell;

pub(super) struct Prothesis;
pub(super) static MODE: Prothesis = Prothesis;

const NAME: &str = "opus-5-5-prothesis";
const KNOBS: usize = 5;
const HELP: &str = "opus-5-5-prothesis: the laying-out of the dead; nothing breathes, the mourners leave, the lamp goes out, and it never loops [vigil] [mourners] [stature] [bier] [night]";

const PARAMS: &[Param] = &[
    param!("VIGIL", "seconds until the room is dark", 10.0, 3600.0, 273.0, 1.0),
    param!("MOURNERS", "mourners at the bier", 0.0, 7.0, 3.0, 1.0),
    param!("STATURE", "body length, share of width", 0.25, 0.8, 0.56, 0.01),
    param!("BIER", "bier line, share of height", 0.45, 0.9, 0.74, 0.01),
    param!("NIGHT", "darkness the lamp leaves behind", 0.0, 1.0, 0.6, 0.05),
];

const VIGIL: usize = 0;
const MOURNERS: usize = 1;
const STATURE: usize = 2;
const BIER: usize = 3;
const NIGHT: usize = 4;

/// The player clock advances 0.06 per 1/60 s tick (`morph.rs`), so 3.6 units per second.
const CLOCK_PER_SECOND: f32 = 3.6;

/// Shroud thickness in rows per column of body length (cells are twice as tall as wide).
const THICK: f32 = 0.09;
/// Bier leg height in rows per column of body length.
const LEGS: f32 = 0.055;

/// Shroud height along the body, head at 0: (position, share of the nose height).
const BODY: [(f32, f32); 31] = [
    (0.000, 0.00),
    (0.004, 0.16),
    (0.012, 0.30),
    (0.024, 0.52),
    (0.038, 0.72),
    (0.054, 0.83),
    (0.068, 0.86),
    (0.076, 0.83),
    (0.088, 1.00),
    (0.096, 0.84),
    (0.103, 0.83),
    (0.110, 0.80),
    (0.118, 0.79),
    (0.128, 0.60),
    (0.146, 0.50),
    (0.170, 0.60),
    (0.210, 0.71),
    (0.270, 0.78),
    (0.335, 0.74),
    (0.380, 0.81),
    (0.425, 0.69),
    (0.520, 0.58),
    (0.640, 0.52),
    (0.700, 0.55),
    (0.800, 0.46),
    (0.880, 0.47),
    (0.925, 0.66),
    (0.952, 0.92),
    (0.968, 0.86),
    (0.986, 0.44),
    (1.000, 0.00),
];

/// Names from Attic grave stelai. The seed chooses who lies here.
const NAMES: [&str; 28] = [
    "HEGESO", "AMPHARETE", "MNESARETE", "PHRASIKLEIA", "MYRRHINE", "KROISOS", "ARISTION",
    "DEXILEOS", "THEANO", "KTESILEOS", "XENOKLEIA", "DAMASISTRATE", "POLYXENA", "ARCHESTRATE",
    "PLANGON", "MELITTA", "EUKOLINE", "MNESAGORA", "NIKOCHARES", "SOSINOS", "THRASEAS",
    "EUANDRIA", "DEMETRIA", "PAMPHILE", "EUPHEROS", "PROKLEIDES", "PHILOXENOS", "PHILOUMENE",
];

const L_NAME: u64 = 0x51;
const L_LEAVE: u64 = 0x52;
const L_FLAME: u64 = 0x53;

/// Fractions of the vigil. Mourners leave inside the window; the lamp gutters, goes out,
/// and the dark settles by 1.0, after which no frame differs from the last.
const LEAVE_FIRST: f32 = 0.10;
const LEAVE_SPAN: f32 = 0.70;
const ARMS_DOWN: f32 = 0.07;
const GUTTER: f32 = 0.88;
const OUT: f32 = 0.92;

impl Mode for Prothesis {
    fn name(&self) -> &'static str {
        NAME
    }
    fn help(&self) -> &'static str {
        HELP
    }
    fn animation(&self) -> AnimKind {
        AnimKind::Iterate
    }
    fn params(&self) -> &'static [Param] {
        PARAMS
    }
    fn render(&self, frame: &mut ModeFrame<'_>) {
        let (args, values) = (frame.args, frame.param_values);
        let p: [f32; KNOBS] = measure_layer(NAME, "knobs", || {
            std::array::from_fn(|i| {
                let param = &PARAMS[i];
                let value = args
                    .get(i + 4)
                    .and_then(|v| v.parse::<f32>().ok())
                    .or_else(|| values.and_then(|v| v.get(i)).copied())
                    .unwrap_or_else(|| param_f32(param.key, param.default));
                if value.is_finite() {
                    value.clamp(param.min, param.max)
                } else {
                    param.default
                }
            })
        });
        draw(frame.grid, frame.width, frame.height, frame.seed, frame.time, &p);
    }
}

/// Splitmix64 over (seed, layer, index, slot); no rng stream is consumed.
#[inline]
fn hash(seed: u64, layer: u64, index: u64, slot: u64) -> u64 {
    let mut z = seed
        ^ layer.wrapping_mul(0x9E37_79B9_7F4A_7C15)
        ^ index.wrapping_mul(0xD1B5_4A32_D192_ED03)
        ^ slot.wrapping_mul(0xC2B2_AE3D_27D4_EB4F);
    z ^= z >> 30;
    z = z.wrapping_mul(0xBF58_476D_1CE4_E5B9);
    z ^= z >> 27;
    z = z.wrapping_mul(0x94D0_49BB_1331_11EB);
    z ^ (z >> 31)
}

#[inline]
fn unit(h: u64) -> f32 {
    (h >> 40) as f32 * (1.0 / 16_777_216.0)
}

#[inline]
fn gray(v: f32) -> Color {
    let v = v.round().clamp(0.0, 255.0) as u8;
    Color::Rgb { r: v, g: v, b: v }
}

/// Where everything stands, from the grid size and the two placement knobs.
struct Layout {
    x0: i32,
    length: usize,
    thick: f32,
    bier_row: i32,
    legs: i32,
    head_row: i32,
}

fn layout(w: usize, h: usize, stature: f32, bier: f32) -> Option<Layout> {
    if w < 24 || h < 10 {
        return None;
    }
    let bier_row = ((bier * h as f32).round() as i32).clamp(5, h as i32 - 2);
    let by_height = ((bier_row as f32 - 3.0) / THICK).floor().max(0.0) as usize;
    let length = ((stature * w as f32).round() as usize)
        .min(by_height)
        .min(w.saturating_sub(14));
    if length < 12 {
        return None;
    }
    let thick = THICK * length as f32;
    let below = h as i32 - 1 - bier_row;
    let legs = ((LEGS * length as f32).round() as i32).clamp(1, (below - 2).max(1));
    let x0 = ((w - length) / 2) as i32 + (0.04 * length as f32).round() as i32;
    let head_row = bier_row - thick.ceil() as i32 - 2;
    Some(Layout { x0, length, thick, bier_row, legs, head_row })
}

/// Fritsch-Carlson tangents so the shroud never overshoots between control points.
fn tangents() -> [f32; 31] {
    let mut d = [0.0f32; 30];
    for i in 0..30 {
        d[i] = (BODY[i + 1].1 - BODY[i].1) / (BODY[i + 1].0 - BODY[i].0);
    }
    let mut m = [0.0f32; 31];
    m[0] = d[0];
    m[30] = d[29];
    for i in 1..30 {
        if d[i - 1] * d[i] > 0.0 {
            let h0 = BODY[i].0 - BODY[i - 1].0;
            let h1 = BODY[i + 1].0 - BODY[i].0;
            let w1 = 2.0 * h1 + h0;
            let w2 = h1 + 2.0 * h0;
            m[i] = (w1 + w2) / (w1 / d[i - 1] + w2 / d[i]);
        }
    }
    m
}

fn shroud(u: f32, m: &[f32; 31]) -> f32 {
    if u <= 0.0 || u >= 1.0 {
        return 0.0;
    }
    let i = BODY.partition_point(|p| p.0 <= u).clamp(1, 30) - 1;
    let (x0, y0) = BODY[i];
    let (x1, y1) = BODY[i + 1];
    let h = x1 - x0;
    let t = (u - x0) / h;
    let (t2, t3) = (t * t, t * t * t);
    (2.0 * t3 - 3.0 * t2 + 1.0) * y0
        + (t3 - 2.0 * t2 + t) * h * m[i]
        + (-2.0 * t3 + 3.0 * t2) * y1
        + (t3 - t2) * h * m[i + 1]
}

/// One column of line: a single glyph, or a stack when the shroud climbs a row or more.
#[derive(Clone, Copy)]
enum Stroke {
    Low,
    Mid,
    DotUp,
    DotDown,
    Tick,
    Back,
    Up(u16),
    Down(u16),
}

#[derive(Clone, Copy)]
struct Step {
    prev: u16,
    stroke: Stroke,
}

const BAND: i32 = 5;
const LEVELS: usize = (2 * BAND + 1) as usize;
const STATES: usize = LEVELS * 3;
const P_TURN: f32 = 1.6;
const P_STACK: f32 = 1.0;
const P_REVERSE: f32 = 2.5;

/// Glyphs attach left and right at quarter rows (`_` 0-0, `.` 0-2, `-` 2-2, `'` 2-4, `/` 0-4);
/// a Viterbi pass picks the connected run nearest the curve: (rows above bier, glyph) per column.
fn trace(mid: &[f32], edge: &[f32]) -> Vec<Vec<(i32, char)>> {
    let n = mid.len();
    let mut bases: Vec<i32> = Vec::with_capacity(n);
    let mut steps: Vec<[Option<Step>; STATES]> = Vec::with_capacity(n);
    let mut prev_base = 0i32;
    let mut prev_cost = [f32::INFINITY; STATES];
    prev_cost[1] = 0.0;
    for c in 0..n {
        let zq = mid[c] * 4.0;
        let ze = edge[c] * 4.0;
        let base = ((ze / 2.0).round() as i32) * 2 - 2 * BAND;
        let (lo, hi) = (base, base + 4 * BAND);
        let mut cost = [f32::INFINITY; STATES];
        let mut step: [Option<Step>; STATES] = [None; STATES];
        for pi in 0..STATES {
            let pc = prev_cost[pi];
            if !pc.is_finite() {
                continue;
            }
            let l = prev_base + 2 * (pi / 3) as i32;
            let pdir = (pi % 3) as i32 - 1;
            if l < 0 {
                continue;
            }
            let mut offer = |r: i32, dir: i32, stroke: Stroke, centre: f32, pen: f32| {
                if r < lo || r > hi || r < 0 {
                    return;
                }
                let mut pen = pen;
                if dir != 0 && pdir != 0 && dir != pdir {
                    pen += P_REVERSE;
                }
                let total = pc + (centre - zq).powi(2) + 0.5 * (r as f32 - ze).powi(2) + pen;
                let idx = ((r - base) / 2) as usize * 3 + (dir + 1) as usize;
                if total < cost[idx] {
                    cost[idx] = total;
                    step[idx] = Some(Step { prev: pi as u16, stroke });
                }
            };
            if l % 4 == 0 {
                let j = (l / 4) as f32;
                offer(l, 0, Stroke::Low, 4.0 * j + 0.3, 0.0);
                offer(l + 2, 1, Stroke::DotUp, 4.0 * j + 1.0, P_TURN);
                if l >= 4 {
                    offer(l - 2, -1, Stroke::Back, 4.0 * j - 1.0, P_TURN);
                }
                let up = ((lo - l + 3).div_euclid(4)).max(1)..=(hi - l).div_euclid(4).min(4096);
                for m in up {
                    let pen = P_STACK * (1.0 + 0.5 * (m - 1) as f32);
                    offer(l + 4 * m, 1, Stroke::Up(m as u16), 4.0 * j + 2.0 * m as f32, pen);
                }
                let down = ((l - hi + 3).div_euclid(4)).max(1)..=(l - lo).div_euclid(4).min(l / 4);
                for m in down {
                    let pen = P_STACK * (1.0 + 0.5 * (m - 1) as f32);
                    let centre = 4.0 * (j - m as f32) + 2.0 * m as f32;
                    offer(l - 4 * m, -1, Stroke::Down(m as u16), centre, pen);
                }
            } else {
                let j = ((l - 2) / 4) as f32;
                offer(l, 0, Stroke::Mid, 4.0 * j + 2.0, 0.0);
                offer(l - 2, -1, Stroke::DotDown, 4.0 * j + 1.0, P_TURN);
                offer(l + 2, 1, Stroke::Tick, 4.0 * j + 3.0, P_TURN);
            }
        }
        if cost.iter().all(|v| !v.is_finite()) {
            break;
        }
        bases.push(base);
        steps.push(step);
        prev_cost = cost;
        prev_base = base;
    }
    let traced = steps.len();
    let mut out = vec![Vec::new(); n];
    if traced == 0 {
        return out;
    }
    let mut idx = (0..STATES)
        .filter(|&i| prev_cost[i].is_finite())
        .min_by(|&a, &b| prev_cost[a].total_cmp(&prev_cost[b]))
        .unwrap_or(1);
    for c in (0..traced).rev() {
        let Some(s) = steps[c][idx] else { break };
        let l = if c == 0 { 0 } else { bases[c - 1] + 2 * (s.prev / 3) as i32 };
        let ends = c < 2 || c + 2 >= n;
        out[c] = match s.stroke {
            Stroke::Low => vec![(l / 4, '_')],
            Stroke::Mid => vec![((l - 2) / 4, '-')],
            Stroke::DotUp => vec![(l / 4, '.')],
            Stroke::DotDown => vec![((l - 2) / 4, '.')],
            Stroke::Tick => vec![((l - 2) / 4, '\'')],
            Stroke::Back => vec![(l / 4 - 1, '`')],
            Stroke::Up(m) => {
                let ch = if ends && m >= 2 { '(' } else { '/' };
                (0..m as i32).map(|k| (l / 4 + k, ch)).collect()
            }
            Stroke::Down(m) => {
                let ch = if ends && m >= 2 { ')' } else { '\\' };
                (0..m as i32).map(|k| ((l - 4 * m as i32) / 4 + k, ch)).collect()
            }
        };
        idx = s.prev as usize;
    }
    out
}

struct Contour {
    key: (usize, u32),
    cols: Vec<Vec<(i32, char)>>,
}

thread_local! {
    static CONTOUR: RefCell<Option<Contour>> = const { RefCell::new(None) };
}

/// The body never moves, so its line is traced once per size and reused for every frame.
fn with_contour<R>(length: usize, thick: f32, f: impl FnOnce(&[Vec<(i32, char)>]) -> R) -> R {
    CONTOUR.with(|cell| {
        let mut slot = cell.borrow_mut();
        let key = (length, thick.to_bits());
        if slot.as_ref().map(|c| c.key) != Some(key) {
            let m = tangents();
            let len = length as f32;
            let mid: Vec<f32> = (0..length).map(|c| shroud((c as f32 + 0.5) / len, &m) * thick).collect();
            let edge: Vec<f32> = (0..length).map(|c| shroud((c as f32 + 1.0) / len, &m) * thick).collect();
            *slot = Some(Contour { key, cols: trace(&mid, &edge) });
        }
        f(&slot.as_ref().expect("contour traced").cols)
    })
}

#[inline]
fn put(grid: &mut Grid, w: usize, h: usize, x: i32, y: i32, ch: char, fg: Color) {
    if x >= 0 && y >= 0 && (x as usize) < w && (y as usize) < h {
        grid[y as usize][x as usize] = Cell::new(ch, fg);
    }
}

/// Light left in the room: the lamp at full until it gutters, then the dark settles by 1.0.
fn room_light(f: f32, night: f32) -> f32 {
    let lamp = if f <= GUTTER {
        1.0
    } else if f >= 1.0 {
        0.0
    } else {
        let x = (f - GUTTER) / (1.0 - GUTTER);
        1.0 - x * x * (3.0 - 2.0 * x)
    };
    1.0 - night * (1.0 - lamp)
}

#[inline]
fn shade(base: f32, keep: f32, light: f32) -> Color {
    gray(base * (keep + (1.0 - keep) * light))
}

fn draw(grid: &mut Grid, w: usize, h: usize, seed: u64, time: f32, p: &[f32; KNOBS]) {
    let (w, h) = (w.min(grid.first().map_or(0, |r| r.len())), h.min(grid.len()));
    let Some(lay) = layout(w, h, p[STATURE], p[BIER]) else {
        return;
    };
    let seconds = time.max(0.0) / CLOCK_PER_SECOND;
    let f = seconds / p[VIGIL];
    let light = room_light(f, p[NIGHT]);
    let len = lay.length as i32;
    let floor_row = lay.bier_row + lay.legs;
    let bier_left = lay.x0 - 2;
    let bier_right = lay.x0 + len + 1;

    measure_layer(NAME, "mourners", || {
        let count = p[MOURNERS].round() as usize;
        let fg = shade(168.0, 0.3, light);
        with_contour(lay.length, lay.thick, |cols| {
            for i in 0..count {
                let leave = LEAVE_FIRST + LEAVE_SPAN * unit(hash(seed, L_LEAVE, i as u64, 0));
                if f >= leave {
                    continue;
                }
                let share = 0.24 + 0.62 * (i as f32 + 0.5) / count as f32;
                let c = (len as f32 * share).round() as usize;
                let x = lay.x0 + c as i32;
                if f < leave - ARMS_DOWN {
                    put(grid, w, h, x - 1, lay.head_row, '/', fg);
                    put(grid, w, h, x + 1, lay.head_row, '\\', fg);
                }
                put(grid, w, h, x, lay.head_row, 'o', fg);
                let crest = cols.get(c).and_then(|cells| cells.iter().map(|&(j, _)| j).max());
                let behind = crest.map_or(lay.bier_row, |j| lay.bier_row - 1 - j);
                for y in lay.head_row + 1..behind {
                    put(grid, w, h, x, y, '|', fg);
                }
            }
        });
    });

    measure_layer(NAME, "body", || {
        let fg = shade(214.0, 0.45, light);
        with_contour(lay.length, lay.thick, |cols| {
            for (c, cells) in cols.iter().enumerate() {
                for &(j, ch) in cells {
                    put(grid, w, h, lay.x0 + c as i32, lay.bier_row - 1 - j, ch, fg);
                }
            }
        });
    });

    measure_layer(NAME, "bier", || {
        let plank = shade(150.0, 0.3, light);
        let leg = shade(118.0, 0.3, light);
        for x in bier_left..=bier_right {
            put(grid, w, h, x, lay.bier_row, '=', plank);
        }
        for y in lay.bier_row + 1..=floor_row {
            put(grid, w, h, bier_left + 1, y, '|', leg);
            put(grid, w, h, bier_right - 1, y, '|', leg);
        }
    });

    measure_layer(NAME, "lamp", || {
        let x = bier_left - 4.max((0.08 * len as f32).round() as i32);
        if x < 1 {
            return;
        }
        let bronze = shade(128.0, 0.3, light);
        let bowl = lay.head_row + 1;
        put(grid, w, h, x - 1, bowl, '\\', bronze);
        put(grid, w, h, x, bowl, '_', bronze);
        put(grid, w, h, x + 1, bowl, '/', bronze);
        for y in bowl + 1..floor_row {
            put(grid, w, h, x, y, '|', bronze);
        }
        put(grid, w, h, x - 1, floor_row, '_', bronze);
        put(grid, w, h, x, floor_row, '|', bronze);
        put(grid, w, h, x + 1, floor_row, '_', bronze);
        if f < GUTTER {
            let phase = unit(hash(seed, L_FLAME, 0, 1));
            let beat = (seconds / 0.6 + phase).floor() as u64;
            let u = unit(hash(seed, L_FLAME, beat, 0));
            let ch = if u < 0.64 { '\'' } else if u < 0.86 { '`' } else { '^' };
            put(grid, w, h, x, lay.head_row, ch, gray(255.0));
        } else if f < OUT {
            put(grid, w, h, x, lay.head_row, '.', gray(176.0));
        }
    });

    measure_layer(NAME, "inscription", || {
        let name = NAMES[(hash(seed, L_NAME, 0, 0) % NAMES.len() as u64) as usize];
        let row = (floor_row + 2).min(h as i32 - 1);
        if row <= floor_row {
            return;
        }
        let spaced = 2 * name.len() as i32 - 1;
        let x = lay.x0 + len / 2 - spaced / 2;
        let fg = shade(140.0, 0.6, light);
        for (i, ch) in name.chars().enumerate() {
            put(grid, w, h, x + 2 * i as i32, row, ch, fg);
        }
    });
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::render::grid_to_plain;
    use rand::{SeedableRng, rngs::StdRng};

    fn knobs() -> Vec<f32> {
        PARAMS.iter().map(|p| p.default).collect()
    }

    fn frame(w: usize, h: usize, seed: u64, time: f32, values: &[f32]) -> Grid {
        let mut grid = vec![vec![Cell::blank(); w]; h];
        let palette = crate::color::make_palette(seed);
        let mut rng = StdRng::seed_from_u64(seed);
        MODE.render(&mut ModeFrame {
            grid: &mut grid,
            width: w,
            height: h,
            seed,
            palette: &palette,
            rng: &mut rng,
            time,
            args: &[],
            param_values: Some(values),
        });
        grid
    }

    fn text(grid: &Grid) -> String {
        grid_to_plain(grid).join("\n")
    }

    fn ink(grid: &Grid) -> usize {
        grid.iter().flatten().filter(|c| c.ch != ' ').count()
    }

    /// Clock time at a fraction of the default vigil.
    fn at(f: f32) -> f32 {
        f * PARAMS[VIGIL].default * CLOCK_PER_SECOND
    }

    #[test]
    fn prothesis_seed42() {
        insta::assert_snapshot!("prothesis_80x24", text(&frame(80, 24, 42, 0.0, &knobs())));
    }

    #[test]
    fn prothesis_seed42_t6() {
        insta::assert_snapshot!("prothesis_80x24_t6", text(&frame(80, 24, 42, 6.0, &knobs())));
    }

    #[test]
    fn prothesis_seed42_vigil_half() {
        insta::assert_snapshot!("prothesis_80x24_half", text(&frame(80, 24, 42, at(0.5), &knobs())));
    }

    #[test]
    fn prothesis_seed42_vigil_end() {
        insta::assert_snapshot!("prothesis_80x24_end", text(&frame(80, 24, 42, at(1.0), &knobs())));
    }

    #[test]
    fn prothesis_seed7_200x60() {
        insta::assert_snapshot!("prothesis_200x60_seed7", text(&frame(200, 60, 7, 0.0, &knobs())));
    }

    #[test]
    fn deterministic_and_seed_names_the_dead() {
        let k = knobs();
        assert_eq!(text(&frame(90, 30, 42, 0.0, &k)), text(&frame(90, 30, 42, 0.0, &k)));
        assert_ne!(text(&frame(90, 30, 42, 0.0, &k)), text(&frame(90, 30, 7, 0.0, &k)));
    }

    #[test]
    fn time_takes_the_mourners_and_the_flame() {
        let k = knobs();
        assert_ne!(text(&frame(90, 30, 42, 0.0, &k)), text(&frame(90, 30, 42, at(1.0), &k)));
    }

    #[test]
    fn time_only_takes_away() {
        let k = knobs();
        let mut last = usize::MAX;
        for i in 0..=240 {
            let n = ink(&frame(120, 36, 42, at(i as f32 / 200.0), &k));
            assert!(n <= last, "ink grew at step {i}: {last} -> {n}");
            last = n;
        }
    }

    #[test]
    fn it_never_loops() {
        let k = knobs();
        let end = frame(120, 36, 42, at(1.0), &k);
        for f in [1.01, 1.5, 3.0, 50.0, 10_000.0] {
            assert!(end == frame(120, 36, 42, at(f), &k), "frame changed after the vigil at {f}");
        }
    }

    #[test]
    fn only_the_flame_moves_while_they_stand() {
        let k = knobs();
        let (w, h) = (90, 30);
        let lay = layout(w, h, k[STATURE], k[BIER]).expect("fits");
        let flame_x = (lay.x0 - 2 - 4.max((0.08 * lay.length as f32).round() as i32)) as usize;
        let flame_y = lay.head_row as usize;
        let first = frame(w, h, 42, 0.0, &k);
        for t in [0.7, 6.0, 13.0, 21.0, 28.0] {
            let later = frame(w, h, 42, t, &k);
            for y in 0..h {
                for x in 0..w {
                    if (x, y) != (flame_x, flame_y) {
                        assert!(first[y][x] == later[y][x], "cell {x},{y} moved at t={t}");
                    }
                }
            }
        }
    }

    #[test]
    fn plain_ascii_at_any_size() {
        let k = knobs();
        for (w, h) in [(80, 24), (200, 60), (31, 11), (400, 120)] {
            assert!(frame(w, h, 42, 0.0, &k).iter().flatten().all(|c| c.ch.is_ascii()));
        }
    }

    #[test]
    fn mostly_silence() {
        let k = knobs();
        let g = frame(80, 24, 42, 0.0, &k);
        assert!(ink(&g) * 100 < 8 * 80 * 24, "80x24 holds {} inked cells", ink(&g));
        let g = frame(200, 60, 42, 0.0, &k);
        assert!(ink(&g) * 100 < 4 * 200 * 60, "200x60 holds {} inked cells", ink(&g));
    }

    #[test]
    fn tiny_and_extreme_grids_stay_in_bounds() {
        let lo: Vec<f32> = PARAMS.iter().map(|p| p.min).collect();
        let hi: Vec<f32> = PARAMS.iter().map(|p| p.max).collect();
        for (w, h) in [(1, 1), (10, 4), (24, 10), (40, 12), (300, 20), (60, 200)] {
            for v in [&lo, &hi, &knobs()] {
                for t in [0.0, at(0.9), at(2.0)] {
                    frame(w, h, 3, t, v);
                }
            }
        }
    }

    #[test]
    fn frame_cost() {
        let (w, h) = (200usize, 60usize);
        let k = knobs();
        let mut worst = 0.0f64;
        let start = std::time::Instant::now();
        for f in 0..100 {
            let t0 = std::time::Instant::now();
            frame(w, h, 42, at(f as f32 / 99.0), &k);
            worst = worst.max(t0.elapsed().as_secs_f64() * 1000.0);
        }
        let avg = start.elapsed().as_secs_f64() * 1000.0 / 100.0;
        eprintln!("{NAME} frame_cost 200x60: avg {avg:.3} ms, worst {worst:.3} ms");
        if !cfg!(debug_assertions) {
            assert!(avg < 6.0, "avg frame {avg:.3} ms");
        }
    }
}
